import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const h=JSON.parse('{"title":"Mobile Task List/Kanban/Calendar, Rich Content Editor, 3-Tier Approvals, Local Reminders & Chat","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/08-mobile-application/mobile-task-workflow/spec.md","filePath":"feature/modules/08-mobile-application/mobile-task-workflow/spec.md"}'),n={name:"feature/modules/08-mobile-application/mobile-task-workflow/spec.md"};function s(i,e,c,d,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="mobile-task-list-kanban-calendar-rich-content-editor-3-tier-approvals-local-reminders-chat" tabindex="-1">Mobile Task List/Kanban/Calendar, Rich Content Editor, 3-Tier Approvals, Local Reminders &amp; Chat <a class="header-anchor" href="#mobile-task-list-kanban-calendar-rich-content-editor-3-tier-approvals-local-reminders-chat" aria-label="Permalink to &quot;Mobile Task List/Kanban/Calendar, Rich Content Editor, 3-Tier Approvals, Local Reminders &amp; Chat&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>mobile-task-workflow</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>08-mobile-application</code> — BrandHub Mobile Application (Expo SDK 58 / React Native 0.88)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>mobile-task-workflow</code>, <code>mobile-native-enhancements (Local Task Reminders &lt;= 40 &amp; Haptics)</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a> (<code>3.6.1–3.6.35</code>) · <a href="./../../../srs/07-publishing-social/README.html">3.8 Publishing &amp; Social</a> (<code>3.8.3–3.8.7</code>)</td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Deliver complete mobile Task &amp; Content execution parity (<code>brandhub-mobile-app</code>): <strong>Task List, Kanban Board &amp; Calendar Timeline</strong> (<code>TaskListScreen</code>, <code>TaskKanbanScreen</code>, <code>CalendarScreen</code>), <strong>Mobile Rich-Text Content Editor &amp; Version History</strong> (<code>ContentWritingEditorScreen</code>, <code>RichTextEditor</code>, <code>SocialPreview</code>), <strong>3-Tier Approval Center</strong> (<code>ApprovalScreen</code> — <code>Creator -&gt; Manager -&gt; Client</code> + Solo <code>self-approve</code>), <strong>Task Comments &amp; Attachments</strong>, <strong>Realtime Workspace Chat</strong> (<code>ChatScreen</code>), and <strong>On-Device Local Deadline Reminders</strong> (<code>taskReminders.ts</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a <code>Creator</code>, <code>Manager</code>, <code>Owner</code>, or <code>Client</code>, I want to manage Tasks across List/Kanban/Calendar views, draft and preview rich social posts, comment with attachments, execute 3-tier approvals with tactile haptic feedback, and receive automatic <code>24h</code> and <code>1h</code> local deadline reminders even without opening the app.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Multi-View Task Management (<code>TaskListScreen.tsx</code>, <code>TaskKanbanScreen.tsx</code>, <code>TaskDetailScreen.tsx</code>, <code>CalendarScreen.tsx</code>):</strong> Supports status/priority/assignee filtering, inline status/assignee updates, subtask checklists, survey summaries (<code>TaskSurveySummaryScreen.tsx</code>), and post dashboard/detail tracking (<code>PostDashboardScreen.tsx</code>, <code>PostDetailScreen.tsx</code>).</li><li><strong>Mobile Rich-Text Editor &amp; Version History (<code>ContentWritingEditorScreen.tsx</code>):</strong> <code>RichTextEditor.tsx</code> + <code>FormattingToolbar.tsx</code> + <code>VersionHistory.tsx</code> + <code>SocialPreview.tsx</code> (<code>Facebook</code>, <code>Instagram</code>, <code>TikTok</code>, <code>Threads</code> mockups) with snapshot save/restore (<code>useTaskContentSync.ts</code>) and compliance moderation banner (<code>editorModeration.ts</code>).</li><li><strong>3-Tier Approval Queue &amp; Comments (<code>ApprovalScreen.tsx</code>):</strong> Supports <code>submit</code>, <code>withdraw</code>, <code>approve</code>, <code>reject</code> (with mandatory revision note), <code>self-approve</code> (Personal Studio), and sectioned task review (<code>taskSectionService.ts</code>) with tactile <code>expo-haptics</code> feedback (<code>haptics.ts</code>).</li><li><strong>On-Device Local Task Deadline Reminders (<code>mobile-native-enhancements</code> AC-R1..R6, <code>taskReminders.ts</code>):</strong> Opt-in setting (<code>NotificationPreferencesScreen.tsx</code>) schedules <code>1 day</code> and <code>1 hour</code> local <code>expo-notifications</code> alerts for open Tasks assigned to the current user (capped at <code>40</code> nearest upcoming notifications respecting iOS <code>64</code>-schedule OS limit), refreshing on app launch, cancelling completed/reassigned tasks, wiping on logout, and deep-linking directly to the Task (switching Workspace safely if needed).</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>tasks.*</code>, <code>approval.*</code>, <code>editor.*</code>, <code>calendar.*</code>, <code>reminders.*</code> in <code>src/i18n/locales/en.json</code> &amp; <code>src/i18n/locales/vi/common.json</code> (<code>tr()</code>)) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> Parity with <code>pages/tasks/*</code>, <code>pages/content-writing/*</code>, <code>pages/calendar/*</code>, <code>pages/chat/*</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/content/{TaskListScreen,TaskKanbanScreen,TaskDetailScreen,PostDetailScreen}.tsx</code>, <code>src/screens/content-writing/*</code>, <code>src/screens/approval/ApprovalScreen.tsx</code>, <code>src/screens/calendar/CalendarScreen.tsx</code>, <code>src/screens/chat/ChatScreen.tsx</code>, <code>src/services/taskReminders.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET/POST/PATCH/DELETE /api/v1/workspaces/{workspaceId}/tasks/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>TaskController</code>, <code>TaskWorkflowController</code>, <code>TaskCommentController</code>, <code>TaskSectionController</code> &lt;- <code>taskService.ts</code></td></tr><tr><td style="text-align:left;">`POST /api/v1/workspaces/{workspaceId}/tasks/{taskId}/{submit</td><td style="text-align:left;">withdraw</td><td style="text-align:left;">approve</td></tr><tr><td style="text-align:left;"><code>GET/POST/PATCH /api/v1/workspaces/{workspaceId}/posts/**</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator, Client</code>)</td><td style="text-align:left;"><code>PostController</code> &lt;- <code>postDashboardService.ts</code> &amp; <code>calendarService.ts</code></td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>OS Notification Permission Denied:</strong> Toggle reverts to <code>off</code> and provides 1-tap link to OS App Settings (<code>Linking.openSettings()</code>).</li><li><strong>iOS 64-Local-Notification Cap:</strong> <code>taskReminders.ts</code> sorts candidate triggers chronologically and schedules at most <code>40</code> nearest future slots.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/05-content-task-workflow/README.html">3.6 Content &amp; Workflow</a> (<code>3.6.1–3.6.35</code>) · <a href="./../../../srs/07-publishing-social/README.html">3.8 Publishing &amp; Social</a> (<code>3.8.3–3.8.7</code>)</li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/05-content-task-workflow.html">BA 05 Content &amp; Task Workflow</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const m=t(n,[["render",s]]);export{h as __pageData,m as default};
